from __future__ import annotations

import itertools
import random

from problems import ThreeColoring, ThreeSat
import reduce as reduce_module


# ----------------------------------------------------------------------
# Solvers (written from the definitions, no external solvers)

def solve_coloring(instance):
    """Brute force 3-colourability: try all 3^n colourings."""
    n = instance["n"]
    edges = instance["edges"]
    for colouring in itertools.product(range(3), repeat=n):
        ok = True
        for u, v in edges:
            if colouring[u] == colouring[v]:
                ok = False
                break
        if ok:
            return True
    return False


def _brute_force_sat(num_vars, clauses):
    """Try all 2^num_vars assignments (only for small num_vars)."""
    for bits in itertools.product((False, True), repeat=num_vars):
        sat = True
        for clause in clauses:
            if not any((bits[abs(l) - 1] if l > 0 else not bits[abs(l) - 1])
                       for l in clause):
                sat = False
                break
        if sat:
            return True
    return False


def _dpll_sat(clauses):
    """Complete DPLL with unit propagation.  clauses: list of frozensets."""
    while True:
        units = [next(iter(c)) for c in clauses if len(c) == 1]
        if not units:
            break
        for u in units:
            new = []
            for c in clauses:
                if u in c:
                    continue
                if -u in c:
                    c2 = c - {-u}
                    if not c2:
                        return False
                    new.append(c2)
                else:
                    new.append(c)
            clauses = new
    if not clauses:
        return True
    # branch on a variable from the shortest clause
    shortest = min(clauses, key=len)
    v = abs(next(iter(shortest)))
    for val in (v, -v):
        new = []
        ok = True
        for c in clauses:
            if val in c:
                continue
            if -val in c:
                c2 = c - {-val}
                if not c2:
                    ok = False
                    break
                new.append(c2)
            else:
                new.append(c)
        if ok and _dpll_sat(new):
            return True
    return False


