    """Complete 3-SAT solver (DPLL)."""
    num_vars = instance["num_vars"]
    clauses = [frozenset(c) for c in instance["clauses"]]
    result = _dpll_sat(clauses)
    # Cross-check with pure brute force when feasible.
    if num_vars <= 16:
        brute = _brute_force_sat(num_vars, instance["clauses"])
        assert result == brute, ("DPLL disagrees with brute force",
                                 num_vars, instance["clauses"], result, brute)
    return result


